# =====================================================
# CSV AND DATA HELPERS
# =====================================================

def load_csv(path, columns=None):
    if os.path.exists(path):
        try:
            return pd.read_csv(path)
        except Exception:
            pass

    return pd.DataFrame(columns=columns) if columns else pd.DataFrame()


def save_csv_row(path, row):
    old = load_csv(path)
    updated = pd.concat(
        [old, pd.DataFrame([row])],
        ignore_index=True
    )
    updated.to_csv(path, index=False, encoding="utf-8-sig")
    return updated


def _is_missing_or_blank(value):
    """Safe scalar missing-value check for mixed and pandas extension dtypes."""
    if value is None:
        return True

    try:
        missing = pd.isna(value)
        if isinstance(missing, bool) and missing:
            return True
    except (TypeError, ValueError):
        pass

    return (
        isinstance(value, str)
        and value.strip().casefold() in {"", "nan", "none", "null"}
    )


def _safe_text_series(series):
    """Convert mixed values to ordinary Python strings."""
    return series.map(
        lambda value: "" if _is_missing_or_blank(value) else str(value)
    )


def flatten_research_for_analytics(frame):
    """Expand Supabase JSONB result groups."""
    import json

    data = (
        frame.copy()
        if isinstance(frame, pd.DataFrame)
        else pd.DataFrame(frame)
    )

    data = data.reset_index(drop=True)

    nested_columns = [
        "physicochemical_results",
        "microbiological_results",
        "contaminant_results",
        "process_data",
        "sensory_results",
        "packaging_results",
    ]

    for column in nested_columns:
        if column not in data.columns:
            continue

        parsed_rows = []

        for raw in data[column].tolist():
            value = raw

            if isinstance(raw, str) and raw.strip():
                try:
                    value = json.loads(raw)
                except (TypeError, ValueError):
                    value = {}

            if not isinstance(value, dict):
                value = {}

            parsed_rows.append(value)

        field_names = []

        for item in parsed_rows:
            for field in item:
                if field not in field_names:
                    field_names.append(field)

        for field in field_names:
            incoming = [item.get(field) for item in parsed_rows]

            if field not in data.columns:
                data[field] = pd.Series(
                    incoming,
                    index=data.index,
                    dtype="object"
                )
                continue

            current = data[field].tolist()

            for index, old_value in enumerate(current):
                if _is_missing_or_blank(old_value) and index < len(incoming):
                    current[index] = incoming[index]

            data[field] = pd.Series(
                current,
                index=data.index,
                dtype="object"
            )

    return data


def load_research_analytics_data():
    """Load observations from Supabase, then use local CSV as fallback."""

    local_data = load_csv(RESEARCH_CSV_FILE)

    try:
        remote_records = get_all_research_observations(page_size=500, max_records=20000)

    except Exception as error:
        if not local_data.empty:
            try:
                return (
                    flatten_research_for_analytics(local_data),
                    "CSV local (secours)",
                    error
                )
            except Exception as local_error:
                return pd.DataFrame(), "Aucune source", local_error

        return pd.DataFrame(), "Aucune source", error

    if remote_records:
        try:
            remote_data = flatten_research_for_analytics(
                pd.DataFrame(remote_records)
            )

            if not remote_data.empty:
                # Merge local-only observations that failed to reach Supabase.
                # V24 observation_id is the primary identity; legacy rows
                # without an ID are reconciled by sample/measurement signature.
                if not local_data.empty:
                    remote_ids = set()
                    if "observation_id" in remote_data.columns:
                        remote_ids = {
                            str(value).strip()
                            for value in remote_data["observation_id"].tolist()
                            if not _is_missing_or_blank(value)
                        }

                    signature_fields = [
                        "batch_id", "product_name", "sample_reference",
                        "sampling_date", "analysis_date", "temperature_celsius",
                        "storage_days", "ph", "total_viable_count",
                        "enterobacteriaceae_count", "coliform_count",
                        "staphylococcus_aureus_count", "salmonella_detected",
                        "nonconformity_detected", "expert_risk_label",
                    ]

                    def _observation_signature(record):
                        values = []
                        for field in signature_fields:
                            value = record.get(field) if hasattr(record, "get") else None
                            if _is_missing_or_blank(value):
                                values.append(None)
                            elif field in {
                                "temperature_celsius", "storage_days", "ph",
                                "total_viable_count", "enterobacteriaceae_count",
                                "coliform_count", "staphylococcus_aureus_count",
                            }:
                                try:
                                    values.append(round(float(value), 8))
                                except (TypeError, ValueError, OverflowError):
                                    values.append(str(value).strip())
                            elif field in {"salmonella_detected", "nonconformity_detected"}:
                                lowered = str(value).strip().casefold()
                                if lowered in {"true", "1", "oui", "yes", "détectée", "detectee"}:
                                    values.append(True)
                                elif lowered in {"false", "0", "non", "no", "non détectée", "non detectee"}:
                                    values.append(False)
                                elif lowered in {"non renseigné", "non renseigne", "non renseignée", "non renseignee", "non évalué", "non evalue", "non analysé", "non analyse", "non testé", "non teste", "indéterminé", "indetermine"}:
                                    values.append(None)
                                else:
                                    values.append(lowered)
                            else:
                                values.append(str(value).strip().casefold())
                        return tuple(values)

                    remote_signature_counts = {}
                    for _, remote_row in remote_data.iterrows():
                        signature = _observation_signature(remote_row)
                        remote_signature_counts[signature] = remote_signature_counts.get(signature, 0) + 1

                    local_seen_without_id = {}
                    local_only_rows = []
                    for _, local_row in local_data.iterrows():
                        local_id = local_row.get("observation_id") if "observation_id" in local_data.columns else None
                        if not _is_missing_or_blank(local_id):
                            if str(local_id).strip() not in remote_ids:
                                local_only_rows.append(local_row.copy())
                            continue

                        signature = _observation_signature(local_row)
                        occurrence = local_seen_without_id.get(signature, 0) + 1
                        local_seen_without_id[signature] = occurrence
                        if occurrence > remote_signature_counts.get(signature, 0):
                            local_only_rows.append(local_row.copy())

                    if local_only_rows:
                        local_only_frame = pd.DataFrame(local_only_rows)
                        local_only_frame["research_source"] = "CSV local — non trouvé dans Supabase"
                        remote_data = pd.concat(
                            [remote_data, local_only_frame],
                            ignore_index=True,
                            sort=False,
                        )

                return remote_data, "Supabase + CSV local", None

        except Exception as error:
            if not local_data.empty:
                try:
                    return (
                        flatten_research_for_analytics(local_data),
                        "CSV local (secours)",
                        error
                    )
                except Exception as local_error:
                    return pd.DataFrame(), "Aucune source", local_error

            return pd.DataFrame(), "Aucune source", error

    if not local_data.empty:
        try:
            return (
                flatten_research_for_analytics(local_data),
                "CSV local (Supabase vide)",
                None
            )
        except Exception as error:
            return pd.DataFrame(), "Aucune source", error

    return pd.DataFrame(), "Aucune source", None


def show_error(title, error):
    """Display useful diagnostics without exposing credentials."""

    st.error(title)
    st.caption(f"Type d'erreur : {type(error).__name__}")

    fields = (
        ("Code", getattr(error, "code", None)),
        ("Message", getattr(error, "message", None)),
        ("Détails", getattr(error, "details", None)),
        ("Indice", getattr(error, "hint", None)),
    )

    shown = False

    for label, value in fields:
        if value:
            st.write(f"**{label} :** {value}")
            shown = True

    if not shown:
        message = str(error)

        message = re.sub(
            r"sb_(?:secret|publishable)_[A-Za-z0-9_-]+",
            "[SECRET MASQUÉ]",
            message
        )

        message = re.sub(
            r"eyJ[A-Za-z0-9._-]{20,}",
            "[TOKEN MASQUÉ]",
            message
        )

        st.caption(
            message[:1200]
            if message
            else "Aucun détail supplémentaire disponible."
        )


def _as_mapping(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
            return parsed if isinstance(parsed, dict) else {}
        except (TypeError, ValueError):
            return {}
    return {}


def _as_text_list(value):
    if isinstance(value, list):
        return " | ".join(str(item) for item in value if item is not None)
    if isinstance(value, str):
        return value
    return ""


def load_risk_history():
    """Prefer persisted Supabase risk assessments; keep legacy CSV as fallback.

    Complete and incomplete sessions are retrieved from Supabase. Local CSV
    records missing remotely are merged in, without double-counting matching
    sessions already present in both stores.
    """
    local_data = load_csv(CSV_FILE)
    try:
        remote_assessments = get_all_risk_assessments(page_size=500, max_records=20000)
        try:
            lots = get_lots(limit=5000)
        except Exception:
            lots = []
    except Exception as error:
        return local_data, "CSV local (secours)", error

    if not remote_assessments:
        return local_data, "CSV local (Supabase vide)", None

    lot_lookup = {
        str(item.get("batch_id") or item.get("batch_code") or "").strip(): item
        for item in lots if (item.get("batch_id") or item.get("batch_code"))
    }
    try:
        from foodnexa_traceability import load_batches
        traceability_batches, _, _ = load_batches()
        for trace_batch in traceability_batches:
            code = str(trace_batch.get("batch_code", "")).strip()
            if code:
                lot_lookup.setdefault(code, trace_batch)
    except Exception:
        pass
    if not local_data.empty and "batch_id" in local_data.columns:
        local_lookup = {
            str(row.get("batch_id", "")).strip(): row
            for _, row in local_data.iterrows()
        }
    else:
        local_lookup = {}

    rows = []
    for item in remote_assessments:
        inputs = _as_mapping(item.get("inputs"))
        lot = lot_lookup.get(str(item.get("batch_id", "")).strip(), {})
        legacy = local_lookup.get(str(item.get("batch_id", "")).strip(), {})
        row = {
            "analysis_date": item.get("analysis_date") or item.get("created_at") or item.get("updated_at"),
            "batch_id": item.get("batch_id"),
            "product_name": item.get("product_name") or lot.get("product_name") or (legacy.get("product_name") if hasattr(legacy, "get") else None),
            "temperature_celsius": inputs.get("temperature_celsius"),
            "storage_days": inputs.get("storage_days"),
            "ph": inputs.get("ph"),
            "cold_chain_broken": inputs.get("cold_chain_broken"),
            "hygiene_controlled": inputs.get("hygiene_controlled"),
            "pasteurized": inputs.get("pasteurized"),
            "risk_score": item.get("risk_score"),
            "risk_level": item.get("risk_level") or (
                "Données incomplètes"
                if str(item.get("analysis_status", "")).casefold() == "données incomplètes"
                else "Non évalué"
            ),
            "confidence": item.get("confidence"),
            "data_completeness": item.get("data_completeness", item.get("confidence")),
            "analysis_status": item.get("analysis_status", "Complete"),
            "reasons": _as_text_list(item.get("reasons")),
            "recommendations": _as_text_list(item.get("recommendations")),
            "history_source": "Supabase",
        }
        factor_scores = _as_mapping(item.get("factor_scores"))
        for key, value in factor_scores.items():
            row[f"{key}_score"] = value
        rows.append(row)

    result = pd.DataFrame(rows)
    # Merge local CSV records that were not persisted remotely. This preserves
    # legacy/local-only history without double-counting records saved to both
    # stores. A multiset comparison keeps genuinely repeated analyses intact.
    if not local_data.empty and "batch_id" in local_data.columns:
        signature_fields = [
            "batch_id", "temperature_celsius", "storage_days", "ph",
            "cold_chain_broken", "hygiene_controlled", "pasteurized",
            "risk_score", "risk_level", "data_completeness", "analysis_status",
        ]

        def _history_signature(record):
            signature = []
            for field in signature_fields:
                if field == "data_completeness":
                    value = record.get(field, record.get("confidence"))
                    if _is_missing_or_blank(value):
                        value = record.get("confidence")
                elif field == "analysis_status":
                    value = record.get(field)
                    if _is_missing_or_blank(value):
                        value = (
                            "Complete"
                            if not _is_missing_or_blank(record.get("risk_score"))
                            and not _is_missing_or_blank(record.get("risk_level"))
                            else "Données incomplètes"
                        )
                else:
                    value = record.get(field) if hasattr(record, "get") else None

                if _is_missing_or_blank(value):
                    signature.append(None)
                    continue
                if field in {"temperature_celsius", "storage_days", "ph", "risk_score", "data_completeness"}:
                    try:
                        signature.append(round(float(value), 8))
                        continue
                    except (TypeError, ValueError, OverflowError):
                        pass
                if field in {"cold_chain_broken", "hygiene_controlled", "pasteurized"}:
                    if isinstance(value, str):
                        lowered = value.strip().casefold()
                        if lowered in {"true", "1", "oui", "yes"}:
                            value = True
                        elif lowered in {"false", "0", "non", "no"}:
                            value = False
                    signature.append(value)
                else:
                    signature.append(str(value).strip())
            return tuple(signature)

        remote_counts = {}
        for _, remote_row in result.iterrows():
            key = _history_signature(remote_row)
            remote_counts[key] = remote_counts.get(key, 0) + 1

        local_only = []
        for _, local_row in local_data.iterrows():
            key = _history_signature(local_row)
            remaining = remote_counts.get(key, 0)
            if remaining > 0:
                remote_counts[key] = remaining - 1
            else:
                row = local_row.copy()
                row["history_source"] = "CSV local — non trouvé dans Supabase"
                local_only.append(row)

        if local_only:
            result = pd.concat([result, pd.DataFrame(local_only)], ignore_index=True, sort=False)

    if "analysis_date" in result.columns:
        result["_sort_date"] = pd.to_datetime(result["analysis_date"], errors="coerce", utc=True)
        result = result.sort_values("_sort_date", ascending=False, na_position="last").drop(columns="_sort_date")
    return result.reset_index(drop=True), "Supabase", None


